## IF, CASE, FOR, WHILE

### IF..ELSIF..ELSE
    IF #niveau < 20.0 THEN
        #pompe := TRUE;
    ELSIF #niveau > 80.0 THEN
        #pompe := FALSE;
    ELSE
        // zone morte, ne rien faire
    END_IF;

### CASE
    CASE #etat OF
        0: #consigne := 0.0;
        1: #consigne := 50.0;
        2: #consigne := 100.0;
        ELSE: #consigne := 0.0;
    END_CASE;

### FOR
    FOR #i := 0 TO 99 DO
        #somme := #somme + #tableau[#i];
    END_FOR;

### WHILE
    WHILE #compteur < 100 AND #etat = 1 DO
        #compteur := #compteur + 1;
    END_WHILE;

[WARN|**Attention aux boucles infinies** en PLC. Un WHILE mal écrit peut bloquer la CPU au cycle. Prévoir toujours une condition de sortie garantie.]

## Fonctions utilitaires

SCL supporte les fonctions à valeur de retour (comme en C/Pascal).

### Appel de fonction
    #resultat := TO_INT(#valeur_reelle);
    #max := MAX(IN1 := #a, IN2 := #b);
    #cos_theta := COS(#theta);

